# Prototype of Student Marks Analytics generated by Rocket
# Translated to standalone Python prototype for testing and local reproduction

def process_marks_ai_v1(raw_str):
    # Initial unprompted Rocket logic (flawed)
    tokens = [t.strip() for t in raw_str.split(",") if t.strip()]
    numbers = []
    for t in tokens:
        try:
            numbers.append(float(t))
        except ValueError:
            pass # ignores strings like abc

    if not numbers:
        return {"valid": 0, "avg": float("nan"), "high": float("-inf"), "low": float("inf"), "pass_rate": float("nan")}

    # Rocket default cutoff was 60%, didn't bound 0-100
    passing = [x for x in numbers if x >= 60]
    return {
        "valid": len(numbers),
        "avg": sum(numbers) / len(numbers),
        "high": max(numbers),
        "low": min(numbers),
        "pass_rate": (len(passing) / len(numbers)) * 100
    }

def process_marks_ai_v2_fixed(raw_str):
    # Fixed Rocket logic after follow-up prompt
    tokens = [t.strip() for t in raw_str.split(",") if t.strip()]
    valid_numbers = []
    for t in tokens:
        try:
            val = float(t)
            if 0 <= val <= 100:
                valid_numbers.append(val)
        except ValueError:
            pass

    if not valid_numbers:
        return "No valid marks provided."

    passing = [x for x in valid_numbers if x >= 50]
    return {
        "valid": len(valid_numbers),
        "avg": sum(valid_numbers) / len(valid_numbers),
        "high": max(valid_numbers),
        "low": min(valid_numbers),
        "pass_rate": (len(passing) / len(valid_numbers)) * 100
    }
